pages.css:
.index-hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: #ffffff;
  padding: var(--spacing-xl) 0;
  text-align: center;
}

.index-hero h1 {
  color: #ffffff;
  margin-bottom: var(--spacing-md);
}

.index-hero-tagline {
  font-size: 1.25rem;
  line-height: 1.6;
  margin-bottom: var(--spacing-lg);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.index-mission {
  padding: var(--spacing-xl) 0;
  background-color: var(--color-bg);
}

.index-mission p {
  font-size: 1.05rem;
  line-height: 1.8;
  color: var(--color-text);
  max-width: 700px;
}

.index-impact {
  background-color: var(--color-bg-alt);
  padding: var(--spacing-xl) 0;
}

.index-impact .card {
  background-color: var(--color-bg);
  text-align: center;
}

.index-impact h3 {
  color: var(--color-primary-dark);
  font-size: 2rem;
  margin-bottom: var(--spacing-sm);
}

.index-programs {
  padding: var(--spacing-xl) 0;
  background-color: var(--color-bg);
}

.index-programs .card h3 {
  color: var(--color-primary-dark);
}

.index-donate {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
  color: #ffffff;
  padding: var(--spacing-xl) 0;
  text-align: center;
}

.index-donate h2 {
  color: #ffffff;
  margin-bottom: var(--spacing-md);
}

.index-donate > .container > p {
  font-size: 1.1rem;
  margin-bottom: var(--spacing-xl);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.index-donate-options {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-lg);
  margin-bottom: var(--spacing-xl);
}

.index-donate-card {
  background-color: rgba(255, 255, 255, 0.1);
  border: 2px solid rgba(255, 255, 255, 0.2);
  border-radius: 6px;
  padding: var(--spacing-lg);
  backdrop-filter: blur(10px);
}

.index-donate-card h3 {
  color: #ffffff;
  margin-bottom: var(--spacing-sm);
}

.index-donate-amount {
  color: var(--color-accent-light);
  font-size: 0.95rem;
  margin-bottom: var(--spacing-md);
}

.index-donate-info {
  background-color: rgba(0, 0, 0, 0.15);
  border-radius: 6px;
  padding: var(--spacing-lg);
  max-width: 600px;
  margin: 0 auto;
  font-size: 0.95rem;
}

.index-donate-info a {
  color: var(--color-accent-light);
  text-decoration: none;
  font-weight: 600;
}

.index-donate-info a:hover {
  color: #ffffff;
  text-decoration: underline;
}

.index-donate-info p {
  margin-bottom: var(--spacing-sm);
}

.index-donate-info p:last-child {
  margin-bottom: 0;
}

@media (max-width: 600px) {
  .index-hero {
    padding: var(--spacing-lg) 0;
  }

  .index-hero-tagline {
    font-size: 1.1rem;
    margin-bottom: var(--spacing-md);
  }

  .index-mission,
  .index-programs,
  .index-donate {
    padding: var(--spacing-lg) 0;
  }

  .index-impact h3 {
    font-size: 1.75rem;
  }

  .index-donate-options {
    grid-template-columns: 1fr;
    margin-bottom: var(--spacing-lg);
  }

  .index-donate > .container > p {
    margin-bottom: var(--spacing-lg);
  }
}

@media (min-width: 601px) {
  .index-hero {
    padding: var(--spacing-xl) 0;
  }

  .index-mission p {
    margin-bottom: var(--spacing-md);
  }
}

